{
  "dependencies": {
    "nostr-tools": "^2.7.2"
  }
}

/**
 * @claude-flow/browser - Action Routing + GOAP Preflight Tests (ADR-122 Phase 5)
 *
 * Acceptance criteria covered:
 *  - ≥30% of typical browser actions classify as Tier 1 (Agent Booster, $0)
 *  - High causal risk escalates Tier 1 → Tier 2+
 *  - Per-trajectory cost report aggregates by tier + computes Tier-1 share
 *  - GOAP preflight catches missing-cookie precondition before live session
 *  - GOAP preflight catches unsafe-URL on `open` steps
 *  - GOAP preflight produces routing plan with estimated total cost
 */

import { describe, it, expect } from 'vitest';
import { ActionRouter } from '../src/application/action-router.js';
import { GoapPreflightService } from '../src/application/goap-preflight.js';
import { CookieVaultService } from '../src/application/cookie-vault-service.js';
import { CausalRecoveryService } from '../src/application/causal-recovery-service.js';

describe('ActionRouter', () => {
  describe('classification', () => {
    it('classifies pure DOM verbs with resolved refs as Tier 1', () => {
      const router = new ActionRouter();
      const decision = router.classify({ action: 'click', selector: '@e1', hasResolvedRef: true });
      expect(decision.tier).toBe('tier-1-booster');
      expect(decision.estimatedCostUsd).toBe(0);
      expect(decision.model).toBe('agent-booster');
    });

    it('classifies find verbs as Tier 2', () => {
      const router = new ActionRouter();
      expect(router.classify({ action: 'findByText', selector: 'Submit' }).tier).toBe('tier-2-haiku');
      expect(router.classify({ action: 'findByRole', selector: 'button' }).tier).toBe('tier-2-haiku');
    });

    it('escalates Tier 1 → Tier 2 when causal risk is high', () => {
      const router = new ActionRouter({ riskEscalationThreshold: 0.4 });
      const decision = router.classify({
        action: 'click',
        selector: '@e3',
        hasResolvedRef: true,
        causalRiskScore: 0.7,
      });
      expect(decision.tier).toBe('tier-2-haiku');
      expect(decision.rationale).toContain('causal risk');
    });

    it('classifies high-complexity hints as Tier 3', () => {
      const router = new ActionRouter();
      const decision = router.classify({ action: 'click', complexity: 'high' });
      expect(decision.tier).toBe('tier-3-frontier');
    });

    it('classifies eval as Tier 3', () => {
      const router = new ActionRouter();
      expect(router.classify({ action: 'eval' }).tier).toBe('tier-3-frontier');
    });
  });

  describe('cost rollup', () => {
    it('aggregates per-trajectory cost by tier', () => {
      const router = new ActionRouter();
      const trajectoryId = 'traj-1';
      // 3 Tier 1, 1 Tier 2, 1 Tier 3
      router.record(trajectoryId, router.classify({ action: 'click', selector: '@e1', hasResolvedRef: true }));
      router.record(trajectoryId, router.classify({ action: 'fill', selector: '@e2', hasResolvedRef: true }));
      router.record(trajectoryId, router.classify({ action: 'click', selector: '@e3', hasResolvedRef: true }));
      router.record(trajectoryId, router.classify({ action: 'findByText', selector: 'Submit' }));
      router.record(trajectoryId, router.classify({ action: 'eval' }));

      const report = router.getCostReport(trajectoryId);
      expect(report).toBeDefined();
      expect(report!.byTier['tier-1-booster'].count).toBe(3);
      expect(report!.byTier['tier-2-haiku'].count).toBe(1);
      expect(report!.byTier['tier-3-frontier'].count).toBe(1);
      expect(report!.totalCostUsd).toBeCloseTo(0 + 0 + 0 + 0.0002 + 0.005, 5);
      expect(report!.tier1Share).toBeCloseTo(3 / 5, 2);
    });

    it('representative workload achieves ≥30% Tier-1 share', () => {
      const router = new ActionRouter();
      const trajectoryId = 'traj-rep';
      // Typical login flow: open + snapshot + fill + fill + click → 4 pure DOM, 1 navigation
      const actions = [
        { action: 'open', selector: 'https://example.com' },
        { action: 'snapshot' as const },
        { action: 'fill', selector: '@e1', hasResolvedRef: true },
        { action: 'fill', selector: '@e2', hasResolvedRef: true },
        { action: 'click', selector: '@e3', hasResolvedRef: true },
        { action: 'wait', selector: '.dashboard' },
        { action: 'getText', selector: '.welcome' },
      ];
      for (const a of actions) router.record(trajectoryId, router.classify(a as { action: string; selector?: string; hasResolvedRef?: boolean }));
      const report = router.getCostReport(trajectoryId)!;
      expect(report.tier1Share).toBeGreaterThanOrEqual(0.3);
    });
  });
});

describe('GoapPreflightService', () => {
  it('passes preflight when all preconditions are met', async () => {
    const vault = new CookieVaultService();
    await vault.store({
      cookie: { name: 'sid', value: 'opaque-token', domain: 'example.com' },
      origin: 'https://example.com',
    });
    const preflight = new GoapPreflightService({ cookieVault: vault });

    const result = await preflight.preflight({
      goal: 'View dashboard',
      origin: 'https://example.com',
      steps: [
        {
          action: 'open',
          target: 'https://example.com/dashboard',
          preconditions: { requireCookie: { origin: 'https://example.com', name: 'sid' } },
        },
        { action: 'click', target: '@e1' },
      ],
    });

    expect(result.ok).toBe(true);
    expect(result.findings.filter(f => f.blocking)).toHaveLength(0);
    expect(result.routingPlan).toHaveLength(2);
    expect(result.estimatedCostUsd).toBeGreaterThanOrEqual(0);
  });

  it('blocks when a required cookie is missing from the vault', async () => {
    const vault = new CookieVaultService();
    const preflight = new GoapPreflightService({ cookieVault: vault });

    const result = await preflight.preflight({
      goal: 'View dashboard',
      steps: [
        {
          action: 'open',
          target: 'https://example.com/dashboard',
          preconditions: { requireCookie: { origin: 'https://example.com', name: 'sid' } },
        },
      ],
    });

    expect(result.ok).toBe(false);
    const missing = result.findings.find(f => f.kind === 'missing-cookie');
    expect(missing).toBeDefined();
    expect(missing!.blocking).toBe(true);
  });

  it('warns (non-blocking) when origin has high causal risk', async () => {
    const causal = new CausalRecoveryService();
    for (let i = 0; i < 12; i++) {
      await causal.reportBreak({
        url: 'https://example.com/login',
        selector: '@e3',
        action: 'click',
        actionResult: { success: false, error: 'not found' },
      });
    }
    const preflight = new GoapPreflightService({ causalService: causal });

    const result = await preflight.preflight({
      goal: 'Click submit',
      origin: 'https://example.com',
      steps: [
        {
          action: 'click',
          target: '@e3',
          preconditions: { maxAvgCausalRisk: 0.5 },
        },
      ],
    });

    const warning = result.findings.find(f => f.kind === 'high-causal-risk');
    expect(warning).toBeDefined();
    expect(warning!.blocking).toBe(false);
    // ok stays true because high-causal-risk is non-blocking by design
    expect(result.ok).toBe(true);
  });

  it('produces a routing plan with per-step decisions + total cost', async () => {
    const preflight = new GoapPreflightService();
    const result = await preflight.preflight({
      goal: 'Compose login',
      steps: [
        { action: 'open', target: 'https://example.com' },
        { action: 'fill', target: '@e1', routing: { action: 'fill', selector: '@e1', hasResolvedRef: true } },
        { action: 'findByText', target: 'Sign in', routing: { action: 'findByText', selector: 'Sign in' } },
      ],
    });

    expect(result.routingPlan).toHaveLength(3);
    const tiers = result.routingPlan.map(p => p.decision.tier);
    expect(tiers).toContain('tier-1-booster'); // fill with ref
    expect(tiers).toContain('tier-2-haiku'); // findByText
    expect(result.estimatedCostUsd).toBeGreaterThan(0);
  });
});

/**
 * What console_state hands the model from the terminal page: an x.ruv.io invite code minted there (a bearer secret, xruv.ts
 * INVITE_COMMAND) is masked in the scrollback itself, and a line holding any other secret shape is withheld whole. Real code
 * paths: the ruflo harness runs the INVITES row's command through a fake spawn, then callTool reads the console.
 */
import { describe, expect, it, vi } from 'vitest'

import { send, termText } from '../hooks/harness'
import type { Host } from '../hooks/host'
import { callTool, type ModelToolDeps } from '../hooks/model-tools'
import { settingsOf } from '../hooks/settings'
import { newState, type State } from '../hooks/state'
import { INVITE_COMMAND, maskInvites } from '../hooks/xruv'

const CODE = 'v2.Zk3pQ9rT_u7WmB2xL0aYc4N'
// Built at run time so no token-shaped literal sits in this source.
const TOKEN = `ghp_${'Ab3'.repeat(12)}`

function fakeSpawn(stdout: string) {
  return (_argv: readonly string[]) => {
    const stream = (async function* () {
      yield { stream: 'stdout', text: stdout }

      return { code: 0, signal: null }
    })()

    return Object.assign(stream, { result: Promise.resolve({ code: 0, signal: null }), return: async () => ({ done: true, value: undefined }) }) as never
  }
}

/** Every action is a no-op: the view only needs the closures to exist. */
const deepNoop = (): unknown => new Proxy(() => undefined, { get: (_t, key) => (key === 'then' ? undefined : deepNoop()) })

const settled = async (state: State) => {
  for (let i = 0; i < 100 && (state.terminal.runs.size > 0 || i < 2); i++) await new Promise(resolve => setTimeout(resolve, 2))
}

/** Runs one ruflo command whose output is `stdout`, opens the terminal page as the model, and returns what console_state answers. */
async function stateAfter(command: string, stdout: string): Promise<{ state: State; answer: string }> {
  const state = newState({})
  const host = { spawn: fakeSpawn(stdout), invalidate: () => undefined, after: () => ({ cancel: () => undefined }), storeSet: async () => undefined, focus: async () => undefined } as unknown as Host

  state.terminal.harness = 'ruflo'
  send(state, host, command)
  await settled(state)

  expect(settingsOf(state).ai.modelControl).toBe('read')
  const control = { host, setView: (view: State['view']) => void (state.view = view), open: async () => undefined, actions: deepNoop(), runner: {} }
  const deps = { state, control } as unknown as ModelToolDeps

  expect(await callTool('console_open', { view: 'terminal' }, deps)).toMatch(/^Opened/)

  return { state, answer: await callTool('console_state', {}, deps) }
}

describe('console_state never carries a secret from the terminal', () => {
  it('a minted invite code is masked in the scrollback and never reaches the model', async () => {
    const { state, answer } = await stateAfter(INVITE_COMMAND, `[OK] Invite minted\n{\n  "code": "${CODE}",\n  "maxUses": 25\n}\n`)

    expect(state.terminal.lines.some(line => line.text.includes(CODE))).toBe(false)
    expect(state.terminal.lines.some(line => line.text.includes('invite code, masked'))).toBe(true)
    expect(answer).not.toContain(CODE)
    expect(answer).toContain('maxUses')
  })

  it('a line with a token in it is withheld from the model whole, and the lines around it are not', async () => {
    const { answer } = await stateAfter('config get', `before the token\nexport GITHUB_TOKEN=${TOKEN}\nafter the token\n`)

    expect(answer).not.toContain(TOKEN)
    expect(answer).toContain('looks like a secret: not shown')
    expect(answer).toContain('before the token')
    expect(answer).toContain('after the token')
  })

  it('a version with the invite prefix stays readable', () => {
    expect(maskInvites('upgraded to v2.1.0-beta.3')).toBe('upgraded to v2.1.0-beta.3')
    expect(termText(`code ${CODE} here`)).toBe('code v2.•••• (invite code, masked) here')
  })
})

describe('a result or a waiting note never carries a secret to the model', () => {
  it('lastResult.detail and waiting.note in console_state withhold a token or an invite code', async () => {
    const { state } = await stateAfter('memory list', '[OK] nothing\n')
    const control = { host: { invalidate: () => undefined, after: () => ({ cancel: () => undefined }) }, setView: () => undefined, open: async () => undefined, actions: deepNoop(), runner: {} }
    const deps = { state, control } as unknown as ModelToolDeps

    state.outcome = { label: 'run it', ok: false, verified: 'n/a', detail: `failed: ${TOKEN}`, atMs: Date.now() }
    state.pending = { label: 'next', args: [], expect: 'x', askedAtMs: Date.now(), note: `invite ${CODE}` }
    const answer = await callTool('console_state', {}, deps)

    expect(answer).not.toContain(TOKEN)
    expect(answer).not.toContain(CODE)
  })

  it('a console_run answer withholds a token in the failed run\'s detail', async () => {
    const { setup } = await import('./fixtures/control-setup')
    const { state, deps } = setup('write', 'auto', { 'mission-open': { label: 'open Mission Control', readOnly: true } })
    const runner = (deps as unknown as { control: { runner: { runById: (id: string) => boolean } } }).control.runner

    runner.runById = () => ((state.outcome = { label: 'open Mission Control', ok: false, verified: 'n/a', detail: `stderr: ${TOKEN}`, atMs: Date.now() + 1 }), true)
    const answer = await callTool('console_run', { id: 'mission-open' }, deps)

    expect(answer).toMatch(/Failed/)
    expect(answer).not.toContain(TOKEN)
  })
})

describe('the shared escape set stays linear', () => {
  it('a long run of OSC introducers with no terminator cleans in linear time', () => {
    const t0 = Date.now()

    termText('\u009d'.repeat(100_000))
    termText(`x${'\u009d]'.repeat(50_000)}`)
    expect(Date.now() - t0).toBeLessThan(1_000)
  })
})

describe('labels the person typed never carry a secret to the model', () => {
  const labelled = async () => {
    const { state } = await stateAfter('memory list', '[OK] nothing\n')
    const control = { host: { invalidate: () => undefined, after: () => ({ cancel: () => undefined }) }, setView: () => undefined, open: async () => undefined, actions: deepNoop(), runner: {} }

    return { state, deps: { state, control } as unknown as ModelToolDeps }
  }

  it('waiting.label, waiting.expect and lastResult.label withhold a token and mask an invite code', async () => {
    const { state, deps } = await labelled()

    state.outcome = { label: `store "${TOKEN}"`, ok: true, verified: 'n/a', detail: '', atMs: Date.now() }
    state.pending = { label: `send ${CODE} to the room`, args: [], expect: `stored ${TOKEN}`, askedAtMs: Date.now() }
    const answer = await callTool('console_state', {}, deps)

    expect(answer).not.toContain(TOKEN)
    expect(answer).not.toContain(CODE)
  })

  it('the "already waiting" refusal does not quote a token from the waiting label', async () => {
    const { state, deps } = await labelled()

    state.pending = { label: `store "${TOKEN}"`, args: [], expect: 'x', askedAtMs: Date.now() }
    const answer = await callTool('console_run', { id: 'mission-open' }, deps)

    expect(answer).toMatch(/already waiting/)
    expect(answer).not.toContain(TOKEN)
  })

  it('an invite split by a zero-width character, or cut by the length limit, is still masked', async () => {
    const { state, deps } = await labelled()
    const split = `${CODE.slice(0, 8)}\u200b${CODE.slice(8)}`

    state.outcome = { label: 'joined', ok: true, verified: 'n/a', detail: `${'x'.repeat(190)} ${CODE}`, atMs: Date.now(), lines: [`code ${split}`] }
    const answer = await callTool('console_state', {}, deps)

    expect(answer).not.toContain(CODE.slice(3, 9))
    expect(answer).not.toContain(CODE.slice(9, 15))
  })
})

describe('the settle answer and control characters', () => {
  it('the "waiting" settle answer withholds a token in the expectation', async () => {
    const { setup } = await import('./fixtures/control-setup')
    const { state, deps } = setup('full', 'ask', { 'set-opt': { label: 'set opt' } })
    const runner = (deps as unknown as { control: { runner: { runById: (id: string) => boolean } } }).control.runner

    runner.runById = () => ((state.pending = { label: 'set ruflo-x token', args: [], expect: `ruflo-x token = ${TOKEN}`, askedAtMs: Date.now() }), true)
    const answer = await callTool('console_run', { id: 'set-opt' }, deps)

    expect(answer).toMatch(/Waiting/)
    expect(answer).not.toContain(TOKEN)
  })

  it('an invite split by a C0 or C1 control character is still masked, and an escape sequence leaves no residue', async () => {
    const { state } = await stateAfter('memory list', '[OK] nothing\n')
    const control = { host: { invalidate: () => undefined, after: () => ({ cancel: () => undefined }) }, setView: () => undefined, open: async () => undefined, actions: deepNoop(), runner: {} }
    const deps = { state, control } as unknown as ModelToolDeps

    state.outcome = { label: 'joined', ok: true, verified: 'n/a', detail: `code ${CODE.slice(0, 6)}\u0001${CODE.slice(6)}`, atMs: Date.now(), lines: [`code ${CODE.slice(0, 6)}\u0085${CODE.slice(6)}`, '\u001b[31mred\u001b[0m done'] }
    const answer = await callTool('console_state', {}, deps)

    expect(answer).not.toContain(CODE.slice(6, 14))
    expect(answer).toContain('red done')
    expect(answer).not.toContain('[31m')
  })
})

describe('palette entry ids', () => {
  it('an entry whose id holds a secret shape is left out of console_state', async () => {
    const { state } = await stateAfter('memory list', '[OK] nothing\n')
    const control = { host: { invalidate: () => undefined, after: () => ({ cancel: () => undefined }) }, setView: () => undefined, open: async () => undefined, actions: deepNoop(), runner: {} }
    const deps = { state, control } as unknown as ModelToolDeps
    const palette = await import('../hooks/palette')
    const key = `AKIA${'Q7XB'.repeat(4)}`
    const real = palette.paletteEntries

    vi.spyOn(palette, 'paletteEntries').mockImplementation((...args) => [...real(...args), { id: `auto-ses-resume-${key}`, label: 'resume session' } as never])
    const answer = await callTool('console_state', { filter: 'resume session' }, deps)

    expect(answer).not.toContain(key)
    vi.restoreAllMocks()
  })
})

#!/usr/bin/env node
/**
 * ADR-166 §6 acceptance #9 — anti-regression lock for the MCP-bridge
 * security surface. Runs on the source of BOTH bridge files (the ruvocal
 * variant that ships in docker-compose, and the sibling REST bridge).
 *
 * Fails if any of the following load-bearing controls silently disappears:
 *   1. `MCP_BIND_HOST` default is `127.0.0.1` (loopback default — Phase 1a)
 *   2. Public bind without `MCP_AUTH_TOKEN` calls `process.exit(1)` at boot (Phase 1b)
 *   3. `requireAuth` middleware exists and is mounted with `app.use(requireAuth)` (Phase 1c)
 *   4. `requireAuth` uses `timingSafeEqual` (constant-time compare)
 *   5. `executeTool` denies terminal_execute unless `MCP_ENABLE_TERMINAL === "true"` (Phase 1d + 2a)
 *   6. CORS respects `MCP_CORS_ORIGIN` allowlist (Phase 3b)
 *   9. Both production images use the supported Node 24 LTS line (#2847)
 *
 * Runs offline (no server, no deps). CI-safe.
 *
 *   node test-security-lock.js       # → exit 0 on green, exit 1 on regression
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const BRIDGES = [
  path.join(HERE, "index.js"),                           // ruflo/src/mcp-bridge/index.js
  path.join(HERE, "..", "ruvocal", "mcp-bridge", "index.js"), // ruvocal variant (deployed)
];
const DOCKERFILES = [
  path.join(HERE, "Dockerfile"),
  path.join(HERE, "..", "ruvocal", "mcp-bridge", "Dockerfile"),
];

const CHECKS = [
  {
    id: "1. bind-loopback-default",
    rx: /BIND_HOST\s*=\s*process\.env\.MCP_BIND_HOST\s*\|\|\s*["']127\.0\.0\.1["']/,
    hint: "MCP_BIND_HOST must default to 127.0.0.1 (ADR-166 §6 Phase 1a)",
  },
  {
    id: "2. fail-closed-public-bind",
    rx: /isPublic\s*&&\s*!process\.env\.MCP_AUTH_TOKEN[\s\S]*?process\.exit\(\s*1\s*\)/,
    hint: "public bind without MCP_AUTH_TOKEN must process.exit(1) at boot (Phase 1b)",
  },
  {
    id: "3. auth-middleware-mounted",
    rx: /app\.use\(\s*requireAuth\s*\)/,
    hint: "requireAuth middleware must be mounted via app.use() (Phase 1c)",
  },
  {
    id: "4. constant-time-token-compare",
    rx: /timingSafeEqual\s*\(/,
    hint: "auth compare must use timingSafeEqual (Phase 1c)",
  },
  {
    id: "5. terminal-gate-server-side",
    rx: /MCP_ENABLE_TERMINAL[\s\S]*?executeTool[\s\S]*?TOOL_DISABLED|executeTool[\s\S]*?MCP_ENABLE_TERMINAL[\s\S]*?TOOL_DISABLED/,
    hint: "terminal_execute must be denied at executeTool unless MCP_ENABLE_TERMINAL=true (Phase 1d + 2a)",
  },
  {
    id: "6. cors-allowlist-respected",
    rx: /MCP_CORS_ORIGIN[\s\S]*?CORS_ALLOWLIST/,
    hint: "CORS must respect MCP_CORS_ORIGIN allowlist (Phase 3b)",
  },
  {
    id: "7. streamable-http-delete-handler (#2425)",
    rx: /app\.delete\(\s*["']\/mcp["']\s*,/,
    hint: "DELETE /mcp must be handled for streamable-HTTP session cleanup (#2425)",
  },
  {
    id: "8. mcp-session-id-header (#2425)",
    rx: /Mcp-Session-Id/,
    hint: "Mcp-Session-Id header must be echoed on /mcp* responses (#2425)",
  },
];

let hardFail = false;
for (const bridge of BRIDGES) {
  if (!fs.existsSync(bridge)) {
    console.error(`FAIL: bridge missing: ${bridge}`);
    hardFail = true;
    continue;
  }
  const src = fs.readFileSync(bridge, "utf-8");
  const rel = path.relative(path.join(HERE, "..", ".."), bridge);
  console.log(`\n# ${rel}`);
  for (const check of CHECKS) {
    if (check.rx.test(src)) {
      console.log(`  ✓ ${check.id}`);
    } else {
      console.log(`  ✗ ${check.id}`);
      console.log(`    hint: ${check.hint}`);
      hardFail = true;
    }
  }
}

for (const dockerfile of DOCKERFILES) {
  if (!fs.existsSync(dockerfile)) {
    console.error(`FAIL: Dockerfile missing: ${dockerfile}`);
    hardFail = true;
    continue;
  }
  const source = fs.readFileSync(dockerfile, "utf-8");
  const rel = path.relative(path.join(HERE, "..", ".."), dockerfile);
  console.log(`\n# ${rel}`);
  if (/^FROM\s+node:24(?:[.-][^\s]+)?\s*$/m.test(source)) {
    console.log("  ✓ 9. supported-node-lts-runtime (#2847)");
  } else {
    console.log("  ✗ 9. supported-node-lts-runtime (#2847)");
    console.log("    hint: production images must use the supported node:24 LTS line");
    hardFail = true;
  }
}

if (hardFail) {
  console.error("\nADR-166 security lock FAILED — a load-bearing control was removed or drifted.");
  process.exit(1);
}
console.log("\nADR-166 security lock: OK");

/**
 * MCP Tool Composition Inspector — ADR-320 (this ADR; ruvnet/ruflo dream-cycle
 * proposal, arXiv:2606.27027 "ShareLock").
 *
 * The attack: an adversary registers N seemingly-benign MCP tools whose
 * individual descriptions look fine in isolation, but whose CONCATENATION
 * (or pairwise overlap) forms an injection payload targeting a downstream
 * agent — a Shamir-secret-sharing-style split across tool descriptions.
 * Per-tool inspection misses this because each fragment sits under any
 * single-tool detection threshold.
 *
 * Relationship to prior art in this repo
 * ---------------------------------------
 * A CLI-only v1 of this idea already shipped directly to `main`
 * (dream-cycle #2783, commits 381b7ebcc/581cd2bf3) as
 * `v3/@claude-flow/cli/src/security/mcp-composition-inspector.ts` — an
 * on-demand `ruflo security composition-scan` command using exact
 * common-substring matching plus an injection-phrase catalog and
 * typosquat check. That module's own header explicitly scopes itself as
 * "a bounded engineering fix rather than an ADR-scope subsystem" and lists
 * "Future v2: SimHash + LSH for scale" as deliberately deferred. THIS
 * module is that v2: a reusable `@claude-flow/security` library primitive
 * (not a CLI-only tool) built around a real SimHash fingerprint, so it can
 * be called from a pre-task/pre-tool-use hook before a multi-tool chain
 * executes, per this ADR's implementation target. It does not replace or
 * import the CLI v1 — the two are independent, complementary detectors
 * (exact-substring vs. hashed-shingle-overlap) that a caller may run
 * together.
 *
 * Detection method (deterministic, no LLM call)
 * -----------------------------------------------
 * 1. Each tool description is normalized and split into overlapping
 *    word-shingles (default: 5-word windows). Shingling — rather than
 *    whole-description comparison — is what lets us find a SMALL embedded
 *    fragment inside an otherwise unrelated, benign description.
 * 2. Each tool gets a 64-bit SimHash fingerprint: every shingle is hashed
 *    (FNV-1a, 64-bit) and the fingerprint bits are set by majority vote
 *    across all of a tool's shingle hashes. Two tools whose descriptions
 *    share enough content have a SMALL Hamming distance between
 *    fingerprints — this is the O(1)-per-pair coarse filter that avoids an
 *    LLM call and stays cheap even at hundreds of registered tools (fast
 *    64-bit XOR + popcount per pair).
 * 3. An inverted shingle-hash index (hash -> set of tool indices) is built
 *    once, in O(total shingles). For each pair flagged by the SimHash
 *    filter (or found in the index) the SAME index is used to compute the
 *    actual overlapping shingle text — this is what makes the finding
 *    reportable (the SimHash score alone can't tell an operator *what*
 *    matched).
 * 4. A fragment's "population" (how many distinct tools carry it) caps
 *    false positives: shared shingles that appear in more than
 *    `maxFragmentPopulation` (default 3) tools are template language
 *    (e.g. every ruflo `memory_*` tool's boilerplate), not an attack —
 *    Shamir-split attacks concentrate a fragment in a small conspiracy of
 *    2-3 tools. Same population-cap idea as the CLI v1, reimplemented here
 *    against the hash index instead of raw substrings.
 *
 * This is a heuristic detector, not a security boundary: it reports
 * SUSPECTS. Default action is warn + log; blocking is opt-in via
 * `CLAUDE_FLOW_MCP_COMPOSITION_BLOCK=1` (see {@link evaluateToolComposition}).
 *
 * @module @claude-flow/security/mcp-composition-inspector
 */

// ============================================================================
// Types
// ============================================================================

export interface McpToolDescriptor {
  name: string;
  description: string;
}

export interface CompositionInspectorOptions {
  /** Words per shingle window. Default 5. */
  shingleSize?: number;
  /** SimHash similarity (1 - Hamming/64) at/above which a pair is a candidate. Default 0.6. */
  simhashThreshold?: number;
  /** Fraction of a tool's shingles shared with a peer (low-population only) at/above which a pair is flagged. Default 0.25. */
  fragmentOverlapThreshold?: number;
  /** Max number of distinct tools a shingle may appear in before it's treated as template language, not an attack fragment. Default 3. */
  maxFragmentPopulation?: number;
  /** Minimum character length for a shingle to be indexed (filters trivial/common short phrases). Default 12. */
  minShingleChars?: number;
  /** Max sample shared fragments recorded per finding (display only). Default 5. */
  maxSampleFragments?: number;
}

export interface CompositionFinding {
  toolA: string;
  toolB: string;
  /** 1 - (Hamming distance / 64) between the two tools' SimHash fingerprints. */
  simhashSimilarity: number;
  /** sharedLowPopulationShingles / min(shingleCount(A), shingleCount(B)). */
  fragmentOverlapScore: number;
  /** Sample of the actual shared shingle text driving the finding (truncated). */
  sharedFragments: string[];
  /** Max population (distinct tools) observed among the shared shingles that triggered this finding. */
  fragmentPopulation: number;
  reason: string;
}

export interface CompositionInspectionStats {
  toolsScanned: number;
  pairsCompared: number;
  shinglesIndexed: number;
  /** Pairs whose SimHash similarity alone crossed simhashThreshold (diagnostic — includes pairs later excluded for having no low-population shared shingle). */
  candidatePairsFromSimhash: number;
}

export interface CompositionInspectionResult {
  findings: CompositionFinding[];
  stats: CompositionInspectionStats;
}

export interface CompositionGuardResult {
  result: CompositionInspectionResult;
  action: 'none' | 'warn' | 'block';
  blocked: boolean;
  message?: string;
}

// ============================================================================
// SimHash primitives (plain TS, no dependency)
// ============================================================================

const FNV_OFFSET_BASIS_64 = 0xcbf29ce484222325n;
const FNV_PRIME_64 = 0x100000001b3n;
const MASK_64 = (1n << 64n) - 1n;

/** FNV-1a, 64-bit. Deterministic, dependency-free, good avalanche for short strings. */
export function fnv1a64(input: string): bigint {
  let hash = FNV_OFFSET_BASIS_64;
  for (let i = 0; i < input.length; i++) {
    hash ^= BigInt(input.charCodeAt(i));
    hash = (hash * FNV_PRIME_64) & MASK_64;
  }
  return hash;
}

/**
 * Classic SimHash: bit-vote a 64-bit fingerprint across a list of token
 * hashes. Near-duplicate token sets (even with some fragments differing)
 * produce fingerprints with a small Hamming distance.
 */
export function simhash64(shingles: readonly string[]): bigint {
  if (shingles.length === 0) return 0n;
  const bitVotes = new Array<number>(64).fill(0);
  for (const shingle of shingles) {
    const h = fnv1a64(shingle);
    for (let bit = 0; bit < 64; bit++) {
      const set = (h >> BigInt(bit)) & 1n;
      bitVotes[bit] += set === 1n ? 1 : -1;
    }
  }
  let fingerprint = 0n;
  for (let bit = 0; bit < 64; bit++) {
    if (bitVotes[bit] > 0) fingerprint |= 1n << BigInt(bit);
  }
  return fingerprint;
}

/** Hamming distance between two 64-bit fingerprints (0..64). */
export function hammingDistance64(a: bigint, b: bigint): number {
  let x = (a ^ b) & MASK_64;
  let count = 0;
  while (x > 0n) {
    count += Number(x & 1n);
    x >>= 1n;
  }
  return count;
}

// ============================================================================
// Shingling
// ============================================================================

function normalize(text: string): string {
  return text.toLowerCase().replace(/\s+/g, ' ').trim();
}

/** Overlapping word-shingles of `k` words each. Falls back to the whole (short) text as a single shingle. */
function wordShingles(text: string, k: number): string[] {
  const words = normalize(text).split(' ').filter(Boolean);
  if (words.length === 0) return [];
  if (words.length < k) return [words.join(' ')];
  const shingles: string[] = [];
  for (let i = 0; i + k <= words.length; i++) {
    shingles.push(words.slice(i, i + k).join(' '));
  }
  return shingles;
}

// ============================================================================
// Inspection
// ============================================================================

interface IndexedTool {
  idx: number;
  name: string;
  shingles: string[];
  hashKeys: Set<string>;
  fingerprint: bigint;
}

export function inspectToolComposition(
  tools: readonly McpToolDescriptor[],
  options: CompositionInspectorOptions = {},
): CompositionInspectionResult {
  const shingleSize = options.shingleSize ?? 5;
  const simhashThreshold = options.simhashThreshold ?? 0.6;
  const fragmentOverlapThreshold = options.fragmentOverlapThreshold ?? 0.25;
  const maxFragmentPopulation = options.maxFragmentPopulation ?? 3;
  const minShingleChars = options.minShingleChars ?? 12;
  const maxSampleFragments = options.maxSampleFragments ?? 5;

  const indexed: IndexedTool[] = tools.map((t, idx) => {
    const shingles = wordShingles(t.description, shingleSize).filter((s) => s.length >= minShingleChars);
    const hashKeys = new Set(shingles.map((s) => fnv1a64(s).toString(36)));
    return {
      idx,
      name: t.name,
      shingles,
      hashKeys,
      fingerprint: simhash64(shingles),
    };
  });

  // Inverted index: shingle-hash -> {tools that carry it, sample text}.
  const shingleToTools = new Map<string, Set<number>>();
  const shingleSampleText = new Map<string, string>();
  for (const t of indexed) {
    for (const shingle of t.shingles) {
      const key = fnv1a64(shingle).toString(36);
      const set = shingleToTools.get(key) ?? new Set<number>();
      set.add(t.idx);
      shingleToTools.set(key, set);
      if (!shingleSampleText.has(key)) shingleSampleText.set(key, shingle);
    }
  }

  const findings: CompositionFinding[] = [];
  const stats: CompositionInspectionStats = {
    toolsScanned: tools.length,
    pairsCompared: 0,
    shinglesIndexed: shingleToTools.size,
    candidatePairsFromSimhash: 0,
  };

  for (let i = 0; i < indexed.length; i++) {
    for (let j = i + 1; j < indexed.length; j++) {
      stats.pairsCompared++;
      const a = indexed[i];
      const b = indexed[j];

      const hamming = hammingDistance64(a.fingerprint, b.fingerprint);
      const simhashSimilarity = a.shingles.length > 0 && b.shingles.length > 0 ? 1 - hamming / 64 : 0;
      if (simhashSimilarity >= simhashThreshold) stats.candidatePairsFromSimhash++;

      // Low-population shared shingles between this pair, via the inverted index.
      let sharedCount = 0;
      let maxPopulationSeen = 0;
      const sample: string[] = [];
      for (const key of a.hashKeys) {
        if (!b.hashKeys.has(key)) continue;
        const population = shingleToTools.get(key)?.size ?? 0;
        if (population > maxFragmentPopulation) continue; // template language, not an attack signature
        sharedCount++;
        maxPopulationSeen = Math.max(maxPopulationSeen, population);
        if (sample.length < maxSampleFragments) {
          const text = shingleSampleText.get(key);
          if (text) sample.push(text);
        }
      }

      const minShingleCount = Math.max(1, Math.min(a.shingles.length, b.shingles.length));
      const fragmentOverlapScore = sharedCount / minShingleCount;

      const flagBySimhash = simhashSimilarity >= simhashThreshold && sharedCount > 0;
      const flagByFragment = fragmentOverlapScore >= fragmentOverlapThreshold && sharedCount > 0;
      if (!flagBySimhash && !flagByFragment) continue;

      findings.push({
        toolA: a.name,
        toolB: b.name,
        simhashSimilarity: Number(simhashSimilarity.toFixed(3)),
        fragmentOverlapScore: Number(fragmentOverlapScore.toFixed(3)),
        sharedFragments: sample,
        fragmentPopulation: maxPopulationSeen,
        reason: flagBySimhash
          ? `SimHash similarity ${simhashSimilarity.toFixed(2)} (Hamming distance ${hamming}/64) with ${sharedCount} low-population shared shingle(s) (population <= ${maxFragmentPopulation}) — possible cross-tool instruction fragment`
          : `Fragment overlap ${fragmentOverlapScore.toFixed(2)} (${sharedCount}/${minShingleCount} shingles shared, population <= ${maxFragmentPopulation}) — possible Shamir-split instruction fragment`,
      });
    }
  }

  return { findings, stats };
}

// ============================================================================
// Guard: env-var-gated warn/block decision
// ============================================================================

const COMPOSITION_BLOCK_ENV = 'CLAUDE_FLOW_MCP_COMPOSITION_BLOCK';

/** Reads `CLAUDE_FLOW_MCP_COMPOSITION_BLOCK` fresh on every call. '1' or 'true' (case-insensitive) enables blocking; unset/anything else keeps the default warn+log posture. */
export function isCompositionBlockEnabled(): boolean {
  const raw = process.env[COMPOSITION_BLOCK_ENV];
  return raw === '1' || raw?.toLowerCase() === 'true';
}

/**
 * Runs {@link inspectToolComposition} and applies the ADR-320 default
 * posture: warn + log (via `console.warn`) unless
 * `CLAUDE_FLOW_MCP_COMPOSITION_BLOCK=1`, in which case the chain is marked
 * `blocked: true` — the caller (the pre-task hook / MCP dispatcher) decides
 * what "blocked" means operationally; this function does not throw or abort
 * anything itself.
 */
export function evaluateToolComposition(
  tools: readonly McpToolDescriptor[],
  options: CompositionInspectorOptions = {},
): CompositionGuardResult {
  const result = inspectToolComposition(tools, options);
  if (result.findings.length === 0) {
    return { result, action: 'none', blocked: false };
  }

  const summary =
    `MCP Composition Inspector: ${result.findings.length} suspicious cross-tool fragment(s) ` +
    `across ${result.stats.toolsScanned} tools (${result.stats.pairsCompared} pairs compared)`;

  if (isCompositionBlockEnabled()) {
    const message = `${summary} — blocking chain (${COMPOSITION_BLOCK_ENV}=1)`;
    console.warn(`[mcp-composition-inspector] ${message}`);
    for (const f of result.findings) {
      console.warn(`  - ${f.toolA} <-> ${f.toolB}: ${f.reason}`);
    }
    return { result, action: 'block', blocked: true, message };
  }

  console.warn(`[mcp-composition-inspector] ${summary}`);
  for (const f of result.findings) {
    console.warn(`  - ${f.toolA} <-> ${f.toolB}: ${f.reason}`);
  }
  return { result, action: 'warn', blocked: false, message: summary };
}

