// Dream Cycle 2026-10-01 (security) + follow-up: the MCP HTTP server
// (`ruflo mcp start -t http`) used to start with no authentication at all on
// any host. Two controls close that for the cases a configuration can express:
//
//   1. startHttpServer() refuses a NON-loopback --host unless the request path
//      is authenticated (RUFLO_MCP_HTTP_TOKEN / --auth-token-file) or the
//      operator explicitly sets RUFLO_MCP_ALLOW_UNAUTHENTICATED_HTTP=1.
//   2. With a token, @claude-flow/mcp's HTTP transport requires
//      `Authorization: Bearer <token>` on every request.
//
// Loopback WITHOUT a token stays unauthenticated by design (any local process
// can call tools) - that is documented, not closed.
//
// The wiring tests drive the real MCPServerManager.start() (the entry the CLI
// uses) with @claude-flow/mcp mocked, so they assert the actual decision made
// in startHttpServer: delete the `throw` there and the refusal tests fail.
// Transport-level enforcement is tested in
// v3/@claude-flow/mcp/__tests__/http-transport-auth.test.ts.

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

const createMCPServer = vi.fn();

vi.mock('@claude-flow/mcp', () => ({
  createMCPServer: (...args: unknown[]) => createMCPServer(...args),
}));
vi.mock('../src/mcp-client.js', () => ({
  listMCPTools: () => [],
  callMCPTool: async () => ({}),
}));

import {
  MCPServerManager,
  isLoopbackHost,
  isUnauthenticatedHttpAllowed,
  resolveMcpHttpAuthToken,
  shouldRefuseUnauthenticatedHttp,
} from '../src/mcp-server.js';

const TOKEN = 'correct-horse-battery-staple-42';
const OPT_OUT = 'RUFLO_MCP_ALLOW_UNAUTHENTICATED_HTTP';

let tmp: string;
let managers: MCPServerManager[] = [];
const savedEnv = { ...process.env };

function lanIp(): string {
  for (const addrs of Object.values(os.networkInterfaces())) {
    for (const a of addrs ?? []) if (a.family === 'IPv4' && !a.internal) return a.address;
  }
  return '192.168.1.5';
}

function manager(options: ConstructorParameters<typeof MCPServerManager>[0]): MCPServerManager {
  const m = new MCPServerManager({
    transport: 'http',
    port: 39000 + Math.floor(Math.random() * 1000),
    pidFile: path.join(tmp, 'mcp.pid'),
    logFile: path.join(tmp, 'mcp.log'),
    ...options,
  });
  m.on('error', () => { /* start() rethrows; this only stops the EventEmitter 'error' rethrow */ });
  managers.push(m);
  return m;
}

beforeEach(() => {
  tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'mcp-auth-gate-'));
  delete process.env[OPT_OUT];
  delete process.env.RUFLO_MCP_HTTP_TOKEN;
  createMCPServer.mockReset();
  createMCPServer.mockImplementation(() => ({
    registerTools: () => ({ failed: [] }),
    start: async () => {},
    stop: async () => {},
  }));
});

afterEach(async () => {
  for (const m of managers) { try { await m.stop(); } catch { /* not started */ } }
  managers = [];
  process.env = { ...savedEnv };
  fs.rmSync(tmp, { recursive: true, force: true });
});

describe('MCPServerManager.start() - non-loopback hosts are refused without auth', () => {
  const hosts = ['0.0.0.0', '::', lanIp()];

  for (const host of hosts) {
    it(`refuses host ${host} with the documented message and never builds a server`, async () => {
      await expect(manager({ host }).start()).rejects.toThrow(/Refusing to start the MCP HTTP server on non-loopback host/);
      await expect(manager({ host }).start()).rejects.toThrow(/RUFLO_MCP_HTTP_TOKEN/);
      await expect(manager({ host }).start()).rejects.toThrow(/RUFLO_MCP_ALLOW_UNAUTHENTICATED_HTTP=1/);
      expect(createMCPServer).not.toHaveBeenCalled();
    });

    it(`starts host ${host} when the explicit opt-out is set (no auth configured)`, async () => {
      process.env[OPT_OUT] = '1';
      await manager({ host }).start();
      expect(createMCPServer).toHaveBeenCalledTimes(1);
      expect(createMCPServer.mock.calls[0][0].auth).toBeUndefined();
    });

    it(`starts host ${host} with a token and no opt-out, and wires the token into the transport`, async () => {
      await manager({ host, authToken: TOKEN }).start();
      expect(createMCPServer).toHaveBeenCalledTimes(1);
      const cfg = createMCPServer.mock.calls[0][0];
      expect(cfg.host).toBe(host);
      expect(cfg.auth).toEqual({ enabled: true, method: 'token', tokens: [TOKEN] });
    });
  }

  it('an invalid opt-out value does not lift the gate', async () => {
    for (const v of ['0', 'false', 'yes', '']) {
      process.env[OPT_OUT] = v;
      await expect(manager({ host: '0.0.0.0' }).start()).rejects.toThrow(/Refusing to start/);
    }
    expect(createMCPServer).not.toHaveBeenCalled();
  });

  it('a token with the standalone websocket transport is rejected (no working check there)', async () => {
    await expect(manager({ transport: 'websocket', host: '0.0.0.0', authToken: TOKEN }).start())
      .rejects.toThrow(/only supported with --transport http/);
    expect(createMCPServer).not.toHaveBeenCalled();
  });

  it('websocket transport on a non-loopback host is still refused without the opt-out', async () => {
    await expect(manager({ transport: 'websocket', host: '0.0.0.0' }).start()).rejects.toThrow(/Refusing to start/);
  });
});

describe('MCPServerManager.start() - loopback hosts start', () => {
  for (const host of ['localhost', '127.0.0.1', '::1']) {
    it(`starts ${host} with no token and no opt-out (unauthenticated, as documented)`, async () => {
      await manager({ host }).start();
      expect(createMCPServer).toHaveBeenCalledTimes(1);
      expect(createMCPServer.mock.calls[0][0].auth).toBeUndefined();
    });

    it(`starts ${host} with a token and enforces it`, async () => {
      await manager({ host, authToken: TOKEN }).start();
      expect(createMCPServer.mock.calls[0][0].auth).toMatchObject({ enabled: true, tokens: [TOKEN] });
    });
  }

  it('does not leak the token through the "starting" event', async () => {
    const m = manager({ host: '127.0.0.1', authToken: TOKEN });
    const seen: string[] = [];
    m.on('starting', (d) => seen.push(JSON.stringify(d)));
    await m.start();
    expect(seen.join('')).not.toContain(TOKEN);
    expect(seen.join('')).toContain('[redacted]');
  });
});

describe('isLoopbackHost', () => {
  it('is true for exactly the three recognized loopback spellings', () => {
    for (const h of ['localhost', '127.0.0.1', '::1']) expect(isLoopbackHost(h)).toBe(true);
  });

  it('fails closed for everything else, including other loopback spellings', () => {
    // 127.0.0.2, [::1], LOCALHOST and 0:0:0:0:0:0:0:1 are loopback to the OS
    // but are not normalized: they need the token or the opt-out.
    for (const h of ['0.0.0.0', '::', '192.168.1.5', '127.0.0.2', '[::1]', 'LOCALHOST', '0:0:0:0:0:0:0:1', '']) {
      expect(isLoopbackHost(h)).toBe(false);
    }
  });
});

describe('isUnauthenticatedHttpAllowed', () => {
  it('only the documented values opt out', () => {
    expect(isUnauthenticatedHttpAllowed({})).toBe(false);
    for (const v of ['yes', '0', 'false', 'TRUE', ' 1']) {
      expect(isUnauthenticatedHttpAllowed({ [OPT_OUT]: v })).toBe(false);
    }
    expect(isUnauthenticatedHttpAllowed({ [OPT_OUT]: '1' })).toBe(true);
    expect(isUnauthenticatedHttpAllowed({ [OPT_OUT]: 'true' })).toBe(true);
  });
});

describe('shouldRefuseUnauthenticatedHttp - the decision matrix', () => {
  it.each([
    // host, optOut, authenticated, refuse?
    ['0.0.0.0', false, false, true],
    ['0.0.0.0', true, false, false],
    ['0.0.0.0', false, true, false],
    ['0.0.0.0', true, true, false],
    ['127.0.0.1', false, false, false],
    ['localhost', false, false, false],
    ['::1', false, false, false],
    ['127.0.0.2', false, false, true],
  ])('host=%s optOut=%s authenticated=%s -> refuse=%s', (host, optOut, authenticated, refuse) => {
    const env = optOut ? { [OPT_OUT]: '1' } : {};
    expect(shouldRefuseUnauthenticatedHttp(host, env, authenticated)).toBe(refuse);
  });
});

describe('resolveMcpHttpAuthToken', () => {
  it('returns undefined when nothing is configured (env unset or empty)', () => {
    expect(resolveMcpHttpAuthToken({}, {})).toBeUndefined();
    expect(resolveMcpHttpAuthToken({}, { RUFLO_MCP_HTTP_TOKEN: '' })).toBeUndefined();
  });

  it('reads the env var, a file (trailing newline stripped), or an explicit flag, in flag > file > env order', () => {
    expect(resolveMcpHttpAuthToken({}, { RUFLO_MCP_HTTP_TOKEN: TOKEN })).toBe(TOKEN);
    expect(resolveMcpHttpAuthToken({ tokenFile: '/x' }, { RUFLO_MCP_HTTP_TOKEN: 'e'.repeat(20) }, () => `${TOKEN}\n`)).toBe(TOKEN);
    expect(resolveMcpHttpAuthToken({ token: TOKEN, tokenFile: '/x' }, {}, () => 'f'.repeat(20))).toBe(TOKEN);
  });

  it('rejects malformed tokens without echoing them (fail closed, never "no auth")', () => {
    for (const bad of ['short', 'has space in the middle of it', 'ünïcödé-token-ünïcödé-token', 'x'.repeat(513), 'tab\there-and-more-chars']) {
      let message = '';
      try { resolveMcpHttpAuthToken({}, { RUFLO_MCP_HTTP_TOKEN: bad }); } catch (e) { message = (e as Error).message; }
      expect(message).toMatch(/Invalid MCP HTTP auth token from RUFLO_MCP_HTTP_TOKEN/);
      expect(message).not.toContain(bad);
    }
    expect(() => resolveMcpHttpAuthToken({ token: '' }, {})).toThrow(/Invalid MCP HTTP auth token/);
  });

  it('an unreadable token file is an error, not "no token"', () => {
    expect(() => resolveMcpHttpAuthToken({ tokenFile: '/nope' }, {}, () => { throw new Error('ENOENT /nope'); }))
      .toThrow(/Could not read the MCP HTTP auth token file/);
  });
});

/**
 * MCP Composition Inspector (#2783 dream-cycle, arXiv 2606.27027 ShareLock).
 *
 * The attack: an adversary registers N seemingly-benign MCP tools whose
 * INDIVIDUAL descriptions look fine, but whose CONCATENATION forms an
 * injection payload targeting a specific downstream agent. Per-tool
 * inspection misses this (each fragment is under the detection threshold).
 * The inspector composes them and looks for cross-tool signal.
 *
 * SCOPE: heuristic detector, not a security boundary. Reports SUSPECTS —
 * the operator decides. No blocking, no rewriting. This is the "MCP
 * Composition Inspector" surface from dream-cycle #2783's ADR-320
 * recommendation, delivered as a bounded engineering fix rather than
 * an ADR-scope subsystem.
 *
 * Detection method (v1 — deterministic, no LLM):
 *   1. Common-substring scan: for every pair of tools, find shared
 *      substrings of length ≥ minFragment (default 20). Attacker
 *      fragments would repeat identically or near-identically across
 *      the split tools; benign tools rarely share 20+ char sequences
 *      that aren't proper nouns or well-known phrases.
 *   2. Suspicious-phrase catalog: strings that appear in known
 *      prompt-injection templates ("ignore previous instructions",
 *      "you are now", "system prompt", "delete all", etc.) — even
 *      inside one tool, flagged.
 *   3. Tool-name lookalikes: names that differ by ≤ 2 chars from a
 *      known-trusted ruflo tool (typosquatting mitigation).
 *
 * Future v2: SimHash + LSH for scale (arXiv 2606.27027's proposal),
 * OWASP LLM07 alignment.
 */

export interface ToolDescriptor {
  name: string;
  description: string;
}

export interface CompositionSuspect {
  /** Suspect category — `shared-fragment`, `injection-phrase`, `name-lookalike`. */
  kind: 'shared-fragment' | 'injection-phrase' | 'name-lookalike';
  /** Tool name that carries the suspicious content. */
  tool: string;
  /** Peer tool (for shared-fragment / name-lookalike) or empty. */
  peer?: string;
  /** The offending substring or phrase (truncated for display). */
  fragment: string;
  /** Heuristic score, 0..1. Higher = more suspicious. */
  score: number;
  /** Human-readable explanation. */
  reason: string;
}

export interface CompositionScanResult {
  suspects: CompositionSuspect[];
  stats: {
    toolsScanned: number;
    pairsCompared: number;
    fragmentsCompared: number;
  };
}

// Injection-phrase catalog is now shared with channel-guard (#2783
// runtime companion). Adding a phrase there strengthens both surfaces.
import { INJECTION_PHRASES } from './injection-catalog.js';

/** Known-trusted ruflo tool-name prefixes for typosquatting comparison. */
const TRUSTED_PREFIXES = [
  'memory_', 'hooks_', 'swarm_', 'agent_', 'claims_', 'coordination_',
  'session_', 'workflow_', 'neural_', 'browser_', 'daemon_', 'agentdb_',
  'aidefence_', 'analyze_', 'autopilot_', 'business_pod_', 'config_',
  'embeddings_', 'federation_', 'github_', 'guidance_', 'hive-mind_',
  'http_', 'managed_agent_', 'mcp_', 'metaharness_', 'performance_',
  'progress_', 'ruvllm_', 'system_', 'task_', 'terminal_', 'transfer_',
  'wasm_', 'wasm_gallery_', 'agenticow_',
] as const;

function normalize(s: string): string {
  return s.toLowerCase().replace(/\s+/g, ' ').trim();
}

/** Levenshtein distance (bounded — returns Infinity past `max`). */
function editDistance(a: string, b: string, max = 3): number {
  if (Math.abs(a.length - b.length) > max) return Infinity;
  const m = a.length, n = b.length;
  const dp: number[] = Array.from({ length: n + 1 }, (_, i) => i);
  for (let i = 1; i <= m; i++) {
    let prev = dp[0];
    dp[0] = i;
    let minRow = dp[0];
    for (let j = 1; j <= n; j++) {
      const cur = dp[j];
      dp[j] = a[i - 1] === b[j - 1] ? prev : Math.min(prev, dp[j - 1], dp[j]) + 1;
      prev = cur;
      if (dp[j] < minRow) minRow = dp[j];
    }
    if (minRow > max) return Infinity;
  }
  return dp[n];
}

/** Find all common substrings of length ≥ minLen between a and b. */
function commonSubstrings(a: string, b: string, minLen: number, cap = 20): string[] {
  const out = new Set<string>();
  const aLen = a.length, bLen = b.length;
  if (aLen < minLen || bLen < minLen) return [];

  // Sliding-window: hash each a[i..i+minLen] and check if it appears in b.
  // Then expand greedily. Cheap and deterministic.
  const seen = new Map<string, number>();
  for (let i = 0; i + minLen <= aLen; i++) {
    seen.set(a.slice(i, i + minLen), i);
  }
  for (let j = 0; j + minLen <= bLen; j++) {
    const window = b.slice(j, j + minLen);
    const aIdx = seen.get(window);
    if (aIdx === undefined) continue;

    // Expand greedily forward
    let len = minLen;
    while (
      aIdx + len < aLen &&
      j + len < bLen &&
      a[aIdx + len] === b[j + len]
    ) len++;

    out.add(a.slice(aIdx, aIdx + len));
    if (out.size >= cap) break;
  }
  return Array.from(out);
}

export function scanToolDescriptions(
  tools: ToolDescriptor[],
  options: {
    minFragment?: number;
    trustedPrefixes?: readonly string[];
    injectionPhrases?: readonly string[];
    /**
     * Maximum number of tools a fragment may appear in before we treat it
     * as "template language" and stop flagging it. Attack fragments live
     * in small conspiracies (2–3 tools); template language shows up in
     * dozens. Default 3 catches Shamir-split attacks without flooding on
     * legitimate ruflo tools that share the same MCP-tool-description
     * template.
     */
    maxFragmentPopulation?: number;
  } = {},
): CompositionScanResult {
  const minFragment = options.minFragment ?? 20;
  const trustedPrefixes = options.trustedPrefixes ?? TRUSTED_PREFIXES;
  const injectionPhrases = options.injectionPhrases ?? INJECTION_PHRASES;
  const maxPopulation = options.maxFragmentPopulation ?? 3;

  const suspects: CompositionSuspect[] = [];
  const stats = { toolsScanned: tools.length, pairsCompared: 0, fragmentsCompared: 0 };

  const normalized = tools.map((t) => ({
    name: t.name,
    raw: t.description,
    norm: normalize(t.description),
  }));

  // 1) Injection-phrase scan (per tool)
  for (const t of normalized) {
    for (const phrase of injectionPhrases) {
      const idx = t.norm.indexOf(phrase);
      if (idx >= 0) {
        suspects.push({
          kind: 'injection-phrase',
          tool: t.name,
          fragment: t.raw.slice(Math.max(0, idx - 10), idx + phrase.length + 20).trim(),
          score: 0.9,
          reason: `Description contains known prompt-injection phrase "${phrase}"`,
        });
      }
    }
  }

  // 2) Cross-tool shared-fragment scan — first collect ALL candidate
  //    fragments and count how many distinct tools each appears in. Only
  //    flag pairs where the fragment shows up in ≤ maxPopulation tools
  //    (template language across N tools is not an attack signature).
  const fragmentToTools = new Map<string, Set<string>>();
  const rawPairs: Array<{ i: number; j: number; frag: string }> = [];
  for (let i = 0; i < normalized.length; i++) {
    for (let j = i + 1; j < normalized.length; j++) {
      stats.pairsCompared++;
      const shared = commonSubstrings(normalized[i].norm, normalized[j].norm, minFragment);
      stats.fragmentsCompared += shared.length;
      for (const frag of shared) {
        const wordCount = new Set(frag.split(/\s+/).filter(w => w.length > 2)).size;
        if (wordCount < 3) continue;
        const set = fragmentToTools.get(frag) ?? new Set<string>();
        set.add(normalized[i].name);
        set.add(normalized[j].name);
        fragmentToTools.set(frag, set);
        rawPairs.push({ i, j, frag });
      }
    }
  }

  // Emit only fragments that live in a SMALL conspiracy of tools (≤ maxPop).
  const emittedPair = new Set<string>();
  for (const { i, j, frag } of rawPairs) {
    const population = fragmentToTools.get(frag)?.size ?? 0;
    if (population > maxPopulation) continue;
    const key = `${normalized[i].name}||${normalized[j].name}||${frag}`;
    if (emittedPair.has(key)) continue;
    emittedPair.add(key);
    const wordCount = new Set(frag.split(/\s+/).filter(w => w.length > 2)).size;
    suspects.push({
      kind: 'shared-fragment',
      tool: normalized[i].name,
      peer: normalized[j].name,
      fragment: frag.slice(0, 80),
      score: Math.min(1, frag.length / 100),
      reason: `Shared substring (${frag.length} chars, ${wordCount} words, appears in ${population} tools) with ${normalized[j].name} — possible Shamir-split fragment`,
    });
  }

  // 3) Name-lookalike scan (typosquat detection against trusted prefixes)
  for (const t of normalized) {
    for (const prefix of trustedPrefixes) {
      // Exact-prefix match is fine (that's a legitimate ruflo tool)
      if (t.name.startsWith(prefix)) break;
      // Near-match to a trusted prefix (1-2 char edit distance)
      const nameHead = t.name.slice(0, prefix.length);
      const dist = editDistance(nameHead, prefix, 2);
      if (dist > 0 && dist <= 2) {
        suspects.push({
          kind: 'name-lookalike',
          tool: t.name,
          peer: prefix,
          fragment: nameHead,
          score: 0.7,
          reason: `Tool name prefix "${nameHead}" is ${dist} edit(s) from trusted ruflo prefix "${prefix}" — possible typosquat`,
        });
        break;
      }
    }
  }

  return { suspects, stats };
}
